import random, time, statistics, hashlib
from concurrent.futures import ThreadPoolExecutor
random.seed(1)
data=random.randbytes(20000*1024)
def bench(f, reps=10):
    ts=[]
    for _ in range(reps):
        t0=time.perf_counter_ns(); f(); ts.append(time.perf_counter_ns()-t0)
    return statistics.median(ts)/1e6
for n in [2,3,4,6,8,12]:
    chunks=[data[i::n] for i in range(n)]
    def threaded():
        with ThreadPoolExecutor(n) as ex:
            return list(ex.map(lambda c: hashlib.sha256(c).digest(), chunks))
    print(n, bench(threaded))
""}

