def _solve_P_Q_fast(U, V):
    P = U + V
    Q = -U + V
    Xd = spsolve(Q, P.toarray())
    X = sparse.csc_matrix(Xd)
    X.eliminate_zeros()
    return X


def _expm_fast(A):
    if len(A.shape) != 2 or A.shape[0] != A.shape[1]:
        raise ValueError('expected a square matrix')
    if A.shape == (0, 0):
        return A.__class__(np.zeros([0, 0], dtype=A.dtype))
    if A.shape == (1, 1):
        return A.__class__([[np.exp(A[0, 0])]])
